#!/usr/bin/env node
// Regenerates types/properties.d.ts from the `csstype` package's property
// names (resolved from the current directory). Development-time only; the
// generated file is committed.
//
//   node scripts/gen-properties.js

import fs from 'node:fs';
import { createRequire } from 'node:module';
import path from 'node:path';
import { REJECTED } from '../src/shorthands.js';

const require = createRequire(path.join(process.cwd(), 'package.json'));
const src = fs.readFileSync(require.resolve('csstype/index.d.ts'), 'utf8');

function keys(name) {
  const i = src.indexOf(`export interface ${name}<`);
  if (i === -1) throw new Error(`csstype: ${name} not found`);
  const body = src.slice(i, src.indexOf('\n}\n', i));
  return [...body.matchAll(/^ {2}([A-Za-z]+)\?:/gm)].map((m) => m[1]);
}

const camel = (kebab) => kebab.replace(/^-/, '').replace(/-([a-z])/g, (_, c) => c.toUpperCase()).replace(/^(webkit|moz)/, (p) => p[0].toUpperCase() + p.slice(1));

// A short list of vendor properties with no standard equivalent.
const VENDOR = [
  'WebkitLineClamp', 'WebkitBoxOrient', 'WebkitFontSmoothing', 'MozOsxFontSmoothing', 'WebkitTapHighlightColor',
  'WebkitTextFillColor', 'WebkitTextStrokeWidth', 'WebkitTextStrokeColor', 'WebkitTouchCallout', 'WebkitOverflowScrolling',
];

const rejected = Object.keys(REJECTED).map(camel);
const all = new Set([...keys('StandardLonghandProperties'), ...keys('StandardShorthandProperties'), ...keys('SvgProperties'), ...VENDOR]);
for (const r of rejected) all.delete(r);
const names = [...all].sort();

const lines = [
  '// Generated by scripts/gen-properties.js from csstype. Do not edit.',
  '',
  '/** CSS properties accepted by css.create (camelCase). */',
  'export type KnownProperty =',
  ...names.map((n, i) => `  | '${n}'${i === names.length - 1 ? ';' : ''}`),
  '',
  '/** Properties that are rejected, mapped to the advice shown by the build. */',
  'export interface RejectedProperties {',
  ...Object.entries(REJECTED).map(([k, v]) => `  ${camel(k)}: 'purser: ${k} is not allowed — ${v.replace(/'/g, "\\'")}';`),
  '}',
  '',
];
fs.writeFileSync(new URL('../types/properties.d.ts', import.meta.url), lines.join('\n'));
console.log(`types/properties.d.ts: ${names.length} properties, ${rejected.length} rejected`);
